mapper.update:
UPDATE ${table}
SET finished_at = CURRENT_TIMESTAMP, status = #{status}, duration_ms = #{durationMs},
    error = #{error}
WHERE id = #{id}

UPDATE ${table}
SET status = 'STALE', finished_at = CURRENT_TIMESTAMP
WHERE status = 'RUNNING' AND started_at < #{olderThan}

mapper.select:
SELECT id, task_name AS taskName, lock_name AS lockName, trigger_time AS triggerTime,
       started_at AS startedAt, finished_at AS finishedAt, host, status, duration_ms AS durationMs
FROM ${table} WHERE task_name = #{taskName} ORDER BY id DESC LIMIT #{limit}
